#[test]
fn imported_portable_cache_key_tracks_content_and_provenance_not_target() {
    let motion = AssetId::generate();
    let provenance_a = AssetId::generate();
    let provenance_b = AssetId::generate();

    let baseline = imported_humanoid_motion_cache_key(
        &motion,
        "fingerprint-a",
        Some(&provenance_a),
    );
    assert_eq!(
        baseline,
        imported_humanoid_motion_cache_key(
            &motion,
            "fingerprint-a",
            Some(&provenance_a),
        )
    );
    assert_ne!(
        baseline,
        imported_humanoid_motion_cache_key(
            &motion,
            "fingerprint-b",
            Some(&provenance_a),
        )
    );
    assert_ne!(
        baseline,
        imported_humanoid_motion_cache_key(
            &motion,
            "fingerprint-a",
            Some(&provenance_b),
        )
    );
}

